<?php

namespace Database\Seeders;

use App\Models\Test;
use Illuminate\Database\Seeder;

class QuestionsSeeder extends Seeder
{
    public function run(): void
    {
        $map = $this->buildQuestionsMap();

        $titles = array_keys($map);

        Test::query()->whereIn('title', $titles)->get()->each(function (Test $test) use ($map) {
            $test->questions()->delete();

            $order = 1;
            foreach ($map[$test->title] as $row) {
                $options = null;
                if ($row['type'] === 'single' && is_array($row['options'])) {
                    $options = array_map(fn ($text) => ['text' => $text], $row['options']);
                }

                $test->questions()->create([
                    'question_text' => $row['text'],
                    'type' => $row['type'],
                    'order' => $row['order'] ?? $order,
                    'options' => $options,
                    'scale_min_label' => $row['scale_min'] ?? null,
                    'scale_max_label' => $row['scale_max'] ?? null,
                    'allow_skip' => true,
                    'age_restrictions' => null,
                ]);
                $order++;
            }
        });
    }

    private function q(string $text, string $type, int $order, ?array $options = null, ?string $scaleMin = null, ?string $scaleMax = null): array
    {
        return [
            'text' => $text,
            'type' => $type,
            'order' => $order,
            'options' => $options,
            'scale_min' => $scaleMin,
            'scale_max' => $scaleMax,
        ];
    }

